// 贝叶斯优化核心：代理模型 + 采集函数选点
let budget = 12;
let kappa  = 2.0;      // ← 探索强度：大=爱探索未知，小=爱利用已知

let observed = [];
for (const x of [3.2, 5.0, 6.8])       // 先撒 3 个起步点
  observed.push({x, y: truef(x)});

while (observed.length < budget) {
  let bestX = null, bestAcq = 1e9;
  for (const x of candidates) {
    const [mu, sd] = predict(observed, x);  // 代理模型
    const acq = mu - kappa * sd;            // ← LCB 采集函数
    if (acq < bestAcq) { bestAcq = acq; bestX = x; }
  }
  observed.push({x: bestX, y: truef(bestX)});
}
const best = observed.reduce((a,b)=> b.y<a.y ? b : a);
console.log(`评估 ${observed.length} 次 · 最优 f=${best.y.toFixed(3)} @ λ=${best.x.toFixed(2)}`);
result = observed;                     // ← 把选中的点交回去绘图

