def can_make_ap(arr):
    diff = arr[1] - arr[0]
    for i in range(1, len(arr)-1):
        if arr[i+1]-arr[i] != diff:
            return False
    return True   # 未排序 → 错

def can_make_ap(arr):
    a = sorted(arr)          # ← 反思：需先 sort
    diff = a[1] - a[0]
    for i in range(1, len(a)-1):
        if a[i+1]-a[i] != diff:
            return False
    return True
